          { key = "fel_concentration", icon = "Spell_Shadow_FingerOfDeath", row = 5, col = 2, max = 3, name = { en = "Fel Concentration", fr = "Gangreconcentration" }, desc = { en = "Your damage-over-time effects last {v}% longer.", fr = "Vos effets de dégâts sur la durée durent {v}% plus longtemps." }, req = "contagion", v = 6 },
          { key = "seed_of_corruption", icon = "Spell_Shadow_CurseOfMannoroth", row = 6, col = 1, max = 1, name = { en = "Seed of Corruption", fr = "Graine de Corruption" }, desc = { en = "Capstone. You start every run with Corruption, and enemies that die afflicted by your damage-over-time effects burst for {v}% of their maximum health on everything within 6 yd.", fr = "Apogée. Vous commencez chaque partie avec Corruption, et les ennemis qui meurent sous vos effets de dégâts sur la durée explosent pour {v}% de leurs points de vie maximum sur tout ce qui se trouve à moins de 6 m." }, capstone = 1 },
