        { name = { en = "Demonology", fr = "Démonologie" }, talents = {
          { key = "demonic_familiar", icon = "Spell_Shadow_SummonImp", row = 0, col = 1, max = 5, name = { en = "Demonic Familiar", fr = "Familier démoniaque" }, desc = { en = "An Imp fights at your side for good, its Firebolts {v}% stronger. Each one also strikes every enemy burning with your Immolate.", fr = "Un diablotin combat à vos côtés pour de bon, ses Éclairs de feu {v}% plus puissants. Chacun frappe aussi tous les ennemis qui brûlent sous votre Immolation." }, v = 4 },
          { key = "demonic_embrace", icon = "Spell_Shadow_Metamorphosis", row = 0, col = 2, max = 5, name = { en = "Demonic Embrace", fr = "Étreinte démoniaque" }, desc = { en = "Increases your maximum health by {v}%.", fr = "Augmente vos points de vie maximum de {v}%." }, v = 4 },
          { key = "fel_stamina", icon = "Spell_Shadow_AntiShadow", row = 1, col = 0, max = 3, name = { en = "Fel Stamina", fr = "Gangrendurance" }, desc = { en = "Reduces all damage taken by {v}%.", fr = "Réduit tous les dégâts subis de {v}%." }, v = 2.5 },
          { key = "unholy_power", icon = "Spell_Shadow_ShadowWordDominate", row = 1, col = 3, max = 5, name = { en = "Unholy Power", fr = "Puissance impie" }, desc = { en = "Your demons deal {v}% more damage.", fr = "Vos démons infligent {v}% de dégâts en plus." }, req = "demonic_familiar", v = 5 },
          { key = "soul_devourer", icon = "Spell_Shadow_SummonFelHunter", row = 2, col = 0, max = 3, name = { en = "Soul Devourer", fr = "Dévoreur d'âmes" }, desc = { en = "Milestone. Permanently summons a Felhunter. Its bites hit 2 enemies, prioritizing bosses and elites, and deal {v}% more damage per 1% missing enemy health.\nConsume Magic: Consumes 10% of your highest-ranked DoT's remaining duration, dealing 150% of the consumed damage.\nRules out Soul Link.", fr = "Palier. Invoque un chasseur corrompu permanent. Ses morsures touchent 2 ennemis, boss et élites en priorité, et infligent {v}% de dégâts en plus par 1% de points de vie manquants de l'ennemi.\nDévorer la magie : consomme 10% de la durée restante de votre effet de dégâts sur la durée de plus haut rang, infligeant 150% des dégâts consommés.\nExclut Lien spirituel." }, req = "demonic_familiar", milestone = 1 },
          { key = "soul_link", icon = "Spell_Shadow_GatherShadows", row = 2, col = 2, max = 3, name = { en = "Soul Link", fr = "Lien spirituel" }, desc = { en = "Milestone. Permanently summons a Voidwalker that hits 2 enemies. Gains 3% damage per 1% Damage Reduction and 2% per 1% bonus max health.\nYour Voidwalkers shield you for {v}% of their damage, up to 25% of your max health.\nRules out Soul Devourer.", fr = "Palier. Invoque un marcheur du Vide permanent qui frappe 2 ennemis. Il gagne 3% de dégâts par 1% de réduction des dégâts et 2% par 1% de points de vie max. bonus.\nVos marcheurs du Vide vous protègent d'un bouclier de {v}% de leurs dégâts, jusqu'à 25% de vos points de vie max.\nExclut Dévoreur d'âmes." }, v = 5, milestone = 1 },
          { key = "felfire_training", icon = "Spell_Shadow_Possession", row = 2, col = 3, max = 3, name = { en = "Demonic Echoes", fr = "Échos démoniaques" }, desc = { en = "Your demons' attacks have a {v}% chance to Echo for full damage. This is their only Echo source.", fr = "Les attaques de vos démons ont {v}% de chances de faire Écho pour la totalité des dégâts. C'est leur seule source d'Écho." }, v = 5 },
          { key = "master_demonologist", icon = "Spell_Shadow_ShadowPact", row = 3, col = 3, max = 3, name = { en = "Master Demonologist", fr = "Maître démonologue" }, desc = { en = "Increases all damage and your demons' critical strike chance by {v}%.", fr = "Augmente tous les dégâts et les chances de coup critique de vos démons de {v}%." }, req = "soul_devourer", v = 3 },
          { key = "legion_gate", icon = "Spell_Shadow_RitualOfSacrifice", row = 4, col = 1, max = 1, name = { en = "Legion Gate", fr = "Porte de la Légion" }, desc = { en = "Milestone. Every 4 sec, summon 3 random lesser demons for 12–16 sec (max 12).\nSuccubi stun Corrupted enemies. Their kills trigger a Death Coil at 50% damage.", fr = "Palier. Toutes les 4 s, invoque 3 démons mineurs aléatoires pendant 12 à 16 s (max. 12).\nLes succubes étourdissent les ennemis affectés par votre Corruption. Leurs victimes déclenchent un Voile mortel à 50% des dégâts." }, milestone = 1 },
          { key = "demonic_supremacy", icon = "Spell_Shadow_CurseOfAchimonde", row = 4, col = 3, max = 1, name = { en = "Demonic Supremacy", fr = "Suprématie démoniaque" }, desc = { en = "Your Infernal and Doomguard become permanent. You can no longer summon lesser demons. Maximum one of each.", fr = "Votre infernal et votre garde funeste deviennent permanents. Vous ne pouvez plus invoquer de démons mineurs. Un seul de chaque au maximum." } },
          { key = "summon_infernal", icon = "Spell_Shadow_SummonInfernal", row = 5, col = 0, max = 3, name = { en = "Summon Infernal", fr = "Invocation d'un infernal" }, desc = { en = "Your damaging spells have a 5% chance to summon an Infernal for 15 sec (max 1). Its Meteor stuns enemies on impact, and it burns nearby enemies with Hellfire at {v}% effectiveness.", fr = "Vos sorts de dégâts ont 5% de chances d'invoquer un infernal pendant 15 s (max. 1). Son météore étourdit les ennemis à l'impact, et il brûle les ennemis proches avec Flammes infernales à {v}% d'efficacité." }, v = 5 },
          { key = "summon_doomguard", icon = "Spell_Shadow_AntiMagicShell", row = 5, col = 3, max = 3, name = { en = "Summon Doomguard", fr = "Invocation d'un garde funeste" }, desc = { en = "Your damaging spells have a 5% chance to summon a Doomguard for 15 sec (max 1). Its Shadow Bolts hit 2 enemies and inherit your upgrades.\nDoom Bringer: Consecutive hits on the same boss or elite deal 20% more damage, up to {v}%.", fr = "Vos sorts de dégâts ont 5% de chances d'invoquer un garde funeste pendant 15 s (max. 1). Ses Traits de l'ombre touchent 2 ennemis et héritent de vos améliorations.\nPorteur de destruction : les coups consécutifs sur le même boss ou élite infligent 20% de dégâts en plus, jusqu'à {v}%." }, req = "legion_gate", v = 5 },
          { key = "pact_of_the_annihilan", icon = "Spell_Shadow_UnholyStrength", row = 6, col = 0, max = 1, name = { en = "Pact of the Annihilan", fr = "Pacte des Annihilans" }, desc = { en = "Capstone. Summons a Pit Lord for {v} sec every 30 sec, reduced by CDR (min 13 sec). Up to 2 active.\nFelseeker inherits your Searing Pain upgrades and deals 25% more damage to its primary target. It hits up to 6 enemies.\nExclusive with Butcher.", fr = "Apogée. Invoque un seigneur des fosses pendant {v} s toutes les 30 s, délai réduit par la réduction des temps de recharge (min. 13 s). Jusqu'à 2 actifs.\nTraque-gangrène hérite des améliorations de votre Douleur brûlante et inflige 25% de dégâts en plus à sa cible principale. Il touche jusqu'à 6 ennemis.\nExclusif avec Boucher." }, req = "legion_gate", v = 20, capstone = 1 },
          { key = "butcher", icon = "Ability_Warrior_Cleave", row = 6, col = 2, max = 1, name = { en = "Butcher", fr = "Boucher" }, desc = { en = "Capstone. Summons a Felguard for {v} sec every 30 sec, reduced by CDR (min 13 sec). Up to 2 active.\nCleaves up to 10 enemies within 15 yd. Every third swing deals double damage. Deals 50% more damage below 30% enemy health.\nExclusive with Pact of the Annihilan.", fr = "Apogée. Invoque un gangregarde pendant {v} s toutes les 30 s, délai réduit par la réduction des temps de recharge (min. 13 s). Jusqu'à 2 actifs.\nEnchaîne jusqu'à 10 ennemis à moins de 15 m. Un coup sur trois inflige le double de dégâts. Inflige 50% de dégâts en plus aux ennemis sous 30% de points de vie.\nExclusif avec Pacte des Annihilans." }, v = 20, capstone = 1 },
